mapper.select:
SELECT FROM tb_bl_bill b LEFT JOIN (SELECT bill_id,sum(rcpt_amt) AS paid FROM tb_bl_rcpt WHERE cncl_yn='N' GROUP BY bill_id) r ON r.bill_id=b.bill_id WHERE
b.bill_ym=replace(#{query.month},'-','')
(left(b.bill_ym,4)=CAST(#{query.year} AS text) OR (left(b.bill_ym,4)<CAST(#{query.year} AS text) AND b.cncl_yn='N' AND b.tot_amt-COALESCE(r.paid,0)>0))
AND b.proj_id=#{query.projectId}
AND (CASE WHEN b.cncl_yn='Y' THEN 'CNCL' WHEN b.tot_amt-COALESCE(r.paid,0)=0 THEN 'PAID' WHEN b.pay_due_dt<#{today} AND b.tot_amt-COALESCE(r.paid,0)>0 THEN 'LATE' ELSE 'UNPAID' END)=#{query.status}
ORDER BY b.bill_dt DESC,b.bill_id DESC
